// The forgery cases of r0-amin-statements.md §12, translated BY HAND
// into their mark obligations (FX008 design §3.4-3.5; Frames.purs,
// Defer.purs, Lend.purs, ResultClauses.purs, MarkUse.purs), each judged
// by `holds` under revision 3.2's obligations and under the earlier
// obligation set that had the hole, beside an honest control program.
// Bounded evidence about these graphs only: the translation is not
// generated by the compiler (that is U6), and no compiler code runs.
import { norm } from './oracle.mjs';

const termOf = marks => name => (name === 'N' || name === 'M' ? name
  : name === 'k1' ? 1 : name === 'k2' ? 2 : marks[name]);
const judged = (obligations, pkg, check) => {
  const term = termOf(pkg.marks);
  return obligations.structural.every(Boolean)
    && obligations.edges.every(([l, h]) => check(term(l), term(h)))
    && obligations.eqs.every(([a, b]) => norm(term(a)) === norm(term(b)));
};
const none = { structural: [], eqs: [] };

// §7a, FX008 §1: `fn work(): Unit with Log = { defer log(1); () }`. x is
// the deferred Log's mark; the declared row's Log is plain (M). E2 at
// `defer` gives M ⊑ x; E6's demand x ⊑ N. Revision 3 lacked E2's edge.
// Control: the same with `with nofail Log` (N ⊑ x).
const cleanup = declared => ({
  current: () => ({ ...none, edges: [[declared, 'x'], ['x', 'N']] }),
  earlier: () => ({ ...none, edges: [['x', 'N']] })
});

// N1: `fn mk(): Handler(nofail Ask with Log)` installed under a caller row
// with Log marked `rho` around `defer Ask.ask()`. m is written N. The
// owned C (ResultC) is R's labels, bare: [Log]. Revision 3.2 derives C
// from the recorded signature; revision 3.1 read it from the package.
// Frames `framed`: m ⊑ f and each C label's paired ρ mark ⊑ f; the body's
// Ask is f; E2 at `defer` f ⊑ y; E6 y ⊑ N.
const ownedC = rho => {
  const edges = c => [['N', 'f'], ...c.map(() => [rho, 'f']), ['f', 'y'],
    ['y', 'N']];
  return {
    current: () => ({ ...none, edges: edges(['Log']) }),
    earlier: pkg => ({ ...none, edges: edges(pkg.c) })
  };
};

// N5: `let h = handler Log { log(n) => fail(E) }` installed around
// `defer Log.log(1)`. m is HandlerLit.m; mi is h's image mark. The clause
// holds Fail: M ⊑ m (Frames `aborting`). E5 reads m from h's type: mi ⊑ f.
// C is Fail(E) only, which FrameOuter skips. E2 at `defer` f ⊑ y; y ⊑ N.
// Revision 3.2 records E1 between the literal's type and h's variable
// (m = mi); revision 3.1 did not. Control: a clause that does not fail
// (no own-abort edge).
const letHandler = aborts => {
  const base = [...(aborts ? [['M', 'm']] : []), ['mi', 'f'], ['f', 'y'],
    ['y', 'N']];
  return {
    current: () => ({ structural: [], edges: base, eqs: [['m', 'mi']] }),
    earlier: () => ({ structural: [], edges: base, eqs: [] })
  };
};

// N4: `fn st(h: Handler(State(Int))): Int with Log = with h { … }`: R is
// the ambient tail alone, ρ is Log plus that tail. Consumption ignoring
// marks is inclusion (R ⊆ ρ, revision 3.2); revision 3.1's E5 said
// equality. No marks.
const inclusion = {
  current: () => ({ ...none, edges: [], structural: [subset([], ['Log'])] }),
  earlier: () => ({ ...none, edges: [], structural: [equal([], ['Log'])] })
};
const subset = (r, rho) => r.every(l => rho.includes(l));
const equal = (r, rho) => subset(r, rho) && subset(rho, r);

const cases = [
  { name: 'cleanup (§7a)', obligations: cleanup('M'),
    packages: { honest: { marks: { x: 'M' } }, forged: { marks: { x: 'N' } } },
    expect: { honest: false, forged: false, forgedEarlier: true } },
  { name: 'cleanup control (nofail Log)', obligations: cleanup('N'),
    packages: { honest: { marks: { x: 'N' } } }, expect: { honest: true } },
  { name: 'owned C forged empty (N1)', obligations: ownedC('M'),
    packages: { honest: { marks: { f: 'M', y: 'M' }, c: ['Log'] },
      forged: { marks: { f: 'N', y: 'N' }, c: [] } },
    expect: { honest: false, forged: false, forgedEarlier: true } },
  { name: 'owned C control (caller nofail Log)', obligations: ownedC('N'),
    packages: { honest: { marks: { f: 'N', y: 'N' }, c: ['Log'] } },
    expect: { honest: true } },
  { name: 'let-bound failing handler (N5)', obligations: letHandler(true),
    packages: { honest: { marks: { m: 'M', mi: 'M', f: 'M', y: 'M' } },
      forged: { marks: { m: 'M', mi: 'N', f: 'N', y: 'N' } } },
    expect: { honest: false, forged: false, forgedEarlier: true } },
  { name: 'let-bound handler control (no fail)', obligations:
    letHandler(false), packages: { honest: { marks: { m: 'N', mi: 'N',
      f: 'N', y: 'N' } } }, expect: { honest: true } },
  { name: 'inclusion with extra effects (N4)', obligations: inclusion,
    packages: { honest: { marks: {} } },
    expect: { honest: true, honestEarlier: false } }
];

export const runCases = check => {
  let failures = 0;
  for (const c of cases) {
    const seen = {};
    for (const [which, pkg] of Object.entries(c.packages)) {
      seen[which] = judged(c.obligations.current(pkg), pkg, check);
      seen[`${which}Earlier`] = judged(c.obligations.earlier(pkg), pkg,
        check);
    }
    const wrong = Object.entries(c.expect).filter(([k, v]) => seen[k] !== v);
    failures += wrong.length;
    console.log(`case ${c.name}: ${JSON.stringify(seen)}`
      + (wrong.length ? `  UNEXPECTED ${JSON.stringify(wrong)}` : ''));
  }
  return failures;
};
